package io.invenlio.warehouse;
import io.invenlio.organization.*;import java.util.*;import org.springframework.context.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.data.domain.*;import org.springframework.data.jpa.domain.Specification;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
@Service class WarehouseService implements WarehouseAvailability{
 private static final Set<String> W_SORT=Set.of("code","name","status","created","updated"),Z_SORT=Set.of("code","name","type","status","sequence","created","updated"),L_SORT=Set.of("code","name","type","status","sequence","created","updated");
 private final AuthorizationService auth;private final AuditTrail audit;private final WarehouseRepository warehouses;private final ZoneRepository zones;private final LocationRepository locations;private final JdbcTemplate jdbc;private final ApplicationEventPublisher events;
 WarehouseService(AuthorizationService a,AuditTrail au,WarehouseRepository w,ZoneRepository z,LocationRepository l,JdbcTemplate j,ApplicationEventPublisher e){auth=a;audit=au;warehouses=w;zones=z;locations=l;jdbc=j;events=e;}
 @Transactional Warehouse create(WarehouseRequest r){var a=auth.require(Permission.WAREHOUSE_CREATE);String code=Warehouse.norm(r.code);if(warehouses.existsByTenantIdAndNormalizedCode(a.tenantId(),code))throw conflict("WAREHOUSE_CODE_EXISTS");try{var w=warehouses.saveAndFlush(new Warehouse(a.tenantId(),r.code,r.name,r.timezone,r.line1,r.line2,r.postal,r.city,r.region,r.country));record(a,"WAREHOUSE_CREATED","warehouse",w.id);events.publishEvent(new WarehouseEvents.WarehouseCreated(a.tenantId(),w.id));return w;}catch(DataIntegrityViolationException e){throw conflict("WAREHOUSE_CODE_EXISTS");}}
 @Transactional(readOnly=true)Warehouse get(UUID id){var a=auth.require(Permission.WAREHOUSE_READ);return warehouse(id,a.tenantId());}
 @Transactional(readOnly=true)Page<Warehouse> list(String q,String status,int page,int size,String sort){var a=auth.require(Permission.WAREHOUSE_READ);Warehouse.Status state=parse(Warehouse.Status.class,status,"INVALID_FILTER");Specification<Warehouse> spec=(root,c,cb)->cb.equal(root.get("tenantId"),a.tenantId());if(q!=null&&!q.isBlank()){String like="%"+q.trim().toLowerCase()+"%";spec=spec.and((root,c,cb)->cb.or(cb.like(cb.lower(root.get("name")),like),cb.like(cb.lower(root.get("normalizedCode")),like)));}if(state!=null)spec=spec.and((root,c,cb)->cb.equal(root.get("status"),state));return warehouses.findAll(spec,page(page,size,sort,W_SORT,"name"));}
 @Transactional Warehouse update(UUID id,WarehouseRequest r,long version){var a=auth.require(Permission.WAREHOUSE_UPDATE);var w=warehouse(id,a.tenantId());String normalized=Warehouse.norm(r.code);if(!normalized.equals(w.normalizedCode)&&warehouses.existsByTenantIdAndNormalizedCode(a.tenantId(),normalized))throw conflict("WAREHOUSE_CODE_EXISTS");w.update(r.code,r.name,r.timezone,r.line1,r.line2,r.postal,r.city,r.region,r.country,version);record(a,"WAREHOUSE_UPDATED","warehouse",id);return w;}
 @Transactional Warehouse transition(UUID id,Warehouse.Status status,long version){var a=auth.require(status==Warehouse.Status.ARCHIVED?Permission.WAREHOUSE_ARCHIVE:Permission.WAREHOUSE_UPDATE);var w=warehouse(id,a.tenantId());w.transition(status,version);String action=status==Warehouse.Status.INACTIVE?"WAREHOUSE_DEACTIVATED":"WAREHOUSE_"+status.name()+"D";record(a,action,"warehouse",id);if(status==Warehouse.Status.ACTIVE)events.publishEvent(new WarehouseEvents.WarehouseActivated(a.tenantId(),id));if(status==Warehouse.Status.ARCHIVED)events.publishEvent(new WarehouseEvents.WarehouseArchived(a.tenantId(),id));return w;}
 @Transactional WarehouseZone zone(UUID warehouseId,ZoneRequest r){var a=auth.require(Permission.WAREHOUSE_LOCATION_MANAGE);warehouse(warehouseId,a.tenantId());String code=Warehouse.norm(r.code);if(zones.existsByTenantIdAndWarehouseIdAndNormalizedCode(a.tenantId(),warehouseId,code))throw conflict("ZONE_CODE_EXISTS");try{var z=zones.saveAndFlush(new WarehouseZone(a.tenantId(),warehouseId,r.code,r.name,parseRequired(WarehouseZone.Type.class,r.type,"INVALID_ZONE_TYPE"),r.sequence));record(a,"ZONE_CREATED","warehouse-zone",z.id);return z;}catch(DataIntegrityViolationException e){throw conflict("ZONE_CODE_EXISTS");}}
 @Transactional(readOnly=true)Page<WarehouseZone> zones(UUID warehouseId,String type,String status,int page,int size,String sort){var a=auth.require(Permission.WAREHOUSE_LOCATION_READ);warehouse(warehouseId,a.tenantId());WarehouseZone.Type kind=parse(WarehouseZone.Type.class,type,"INVALID_FILTER");WarehouseZone.Status state=parse(WarehouseZone.Status.class,status,"INVALID_FILTER");Specification<WarehouseZone> spec=(root,c,cb)->cb.and(cb.equal(root.get("tenantId"),a.tenantId()),cb.equal(root.get("warehouseId"),warehouseId));if(kind!=null)spec=spec.and((root,c,cb)->cb.equal(root.get("type"),kind));if(state!=null)spec=spec.and((root,c,cb)->cb.equal(root.get("status"),state));return zones.findAll(spec,page(page,size,sort,Z_SORT,"sequence"));}
 @Transactional(readOnly=true)WarehouseZone getZone(UUID id){var a=auth.require(Permission.WAREHOUSE_LOCATION_READ);return zone(id,a.tenantId());}
 @Transactional WarehouseZone updateZone(UUID id,ZoneRequest r,long version){var a=auth.require(Permission.WAREHOUSE_LOCATION_MANAGE);var z=zone(id,a.tenantId());String code=Warehouse.norm(r.code);if(!code.equals(z.normalizedCode)&&zones.existsByTenantIdAndWarehouseIdAndNormalizedCode(a.tenantId(),z.warehouseId,code))throw conflict("ZONE_CODE_EXISTS");z.update(r.code,r.name,parseRequired(WarehouseZone.Type.class,r.type,"INVALID_ZONE_TYPE"),r.sequence,version);record(a,"ZONE_UPDATED","warehouse-zone",id);return z;}
 @Transactional WarehouseZone archiveZone(UUID id,long version){var a=auth.require(Permission.WAREHOUSE_LOCATION_MANAGE);var z=zone(id,a.tenantId());if(locations.existsByTenantIdAndWarehouseIdAndZoneIdAndStatusNot(a.tenantId(),z.warehouseId,id,StorageLocation.Status.ARCHIVED))throw new WarehouseException("ZONE_HAS_ACTIVE_LOCATIONS","Archive zone locations first");z.archive(version);record(a,"ZONE_ARCHIVED","warehouse-zone",id);return z;}
 @Transactional StorageLocation location(UUID warehouseId,LocationRequest r){var a=auth.require(Permission.WAREHOUSE_LOCATION_MANAGE);warehouse(warehouseId,a.tenantId());requireZone(r.zoneId,a.tenantId(),warehouseId);validateParent(a.tenantId(),warehouseId,r.zoneId,r.parentId,null);String code=Warehouse.norm(r.code),scan=Warehouse.norm(r.scanCode);if(locations.existsByTenantIdAndWarehouseIdAndNormalizedCode(a.tenantId(),warehouseId,code))throw conflict("LOCATION_CODE_EXISTS");if(locations.existsByTenantIdAndNormalizedScanCode(a.tenantId(),scan))throw conflict("LOCATION_SCAN_CODE_EXISTS");try{var l=locations.saveAndFlush(new StorageLocation(a.tenantId(),warehouseId,r.zoneId,r.parentId,r.code,r.name,parseRequired(StorageLocation.Type.class,r.type,"INVALID_LOCATION_TYPE"),r.sequence,r.scanCode,r.maxWeight,r.maxVolume,r.maxPallets,r.length,r.width,r.height));record(a,"LOCATION_CREATED","warehouse-location",l.id);events.publishEvent(new WarehouseEvents.LocationCreated(a.tenantId(),l.id));return l;}catch(DataIntegrityViolationException e){throw new WarehouseException("LOCATION_CONFLICT","Location code or scan code conflicts");}}
 @Transactional(readOnly=true)StorageLocation getLocation(UUID id){var a=auth.require(Permission.WAREHOUSE_LOCATION_READ);return location(id,a.tenantId());}
 @Transactional(readOnly=true)Page<StorageLocation> locations(UUID warehouseId,UUID zoneId,UUID parentId,String type,String status,String code,String q,int page,int size,String sort){var a=auth.require(Permission.WAREHOUSE_LOCATION_READ);warehouse(warehouseId,a.tenantId());StorageLocation.Type kind=parse(StorageLocation.Type.class,type,"INVALID_FILTER");StorageLocation.Status state=parse(StorageLocation.Status.class,status,"INVALID_FILTER");Specification<StorageLocation> spec=(root,c,cb)->cb.and(cb.equal(root.get("tenantId"),a.tenantId()),cb.equal(root.get("warehouseId"),warehouseId));if(zoneId!=null)spec=spec.and((root,c,cb)->cb.equal(root.get("zoneId"),zoneId));if(parentId!=null)spec=spec.and((root,c,cb)->cb.equal(root.get("parentId"),parentId));if(kind!=null)spec=spec.and((root,c,cb)->cb.equal(root.get("type"),kind));if(state!=null)spec=spec.and((root,c,cb)->cb.equal(root.get("status"),state));if(code!=null&&!code.isBlank()){String exact=Warehouse.norm(code);spec=spec.and((root,c,cb)->cb.equal(root.get("normalizedCode"),exact));}if(q!=null&&!q.isBlank()){String like="%"+q.trim().toLowerCase()+"%";spec=spec.and((root,c,cb)->cb.or(cb.like(cb.lower(root.get("name")),like),cb.like(cb.lower(root.get("normalizedCode")),like)));}return locations.findAll(spec,page(page,size,sort,L_SORT,"sequence"));}
 @Transactional StorageLocation updateLocation(UUID id,LocationUpdate r){var a=auth.require(Permission.WAREHOUSE_LOCATION_MANAGE);var l=location(id,a.tenantId());requireZone(r.zoneId,a.tenantId(),l.warehouseId);validateParent(a.tenantId(),l.warehouseId,r.zoneId,l.parentId,id);l.update(r.zoneId,r.name,parseRequired(StorageLocation.Type.class,r.type,"INVALID_LOCATION_TYPE"),r.sequence,r.maxWeight,r.maxVolume,r.maxPallets,r.length,r.width,r.height,r.version);record(a,"LOCATION_UPDATED","warehouse-location",id);return l;}
 @Transactional StorageLocation move(UUID id,UUID parentId,long version){var a=auth.require(Permission.WAREHOUSE_LOCATION_MANAGE);var l=location(id,a.tenantId());validateParent(a.tenantId(),l.warehouseId,l.zoneId,parentId,id);l.move(parentId,version);record(a,"LOCATION_MOVED","warehouse-location",id);events.publishEvent(new WarehouseEvents.LocationMoved(a.tenantId(),id));return l;}
 @Transactional StorageLocation status(UUID id,String action,long version){var a=auth.require(Permission.WAREHOUSE_LOCATION_MANAGE);var l=location(id,a.tenantId());if(action.equals("BLOCK"))l.block(version);else if(action.equals("UNBLOCK"))l.unblock(version);else{if(locations.existsByTenantIdAndWarehouseIdAndParentIdAndStatusNot(a.tenantId(),l.warehouseId,id,StorageLocation.Status.ARCHIVED))throw new WarehouseException("LOCATION_HAS_ACTIVE_CHILDREN","Archive children first");l.archive(version);}String auditAction=action.equals("BLOCK")?"LOCATION_BLOCKED":action.equals("UNBLOCK")?"LOCATION_UNBLOCKED":"LOCATION_ARCHIVED";record(a,auditAction,"warehouse-location",id);return l;}
 @Transactional void assignDefault(UUID warehouseId,String purpose,UUID locationId){var a=auth.require(Permission.WAREHOUSE_LOCATION_MANAGE);warehouse(warehouseId,a.tenantId());if(!Set.of("RECEIVING","SHIPPING","RETURNS","QUARANTINE","DAMAGED").contains(purpose))throw new WarehouseException("INVALID_LOCATION_PURPOSE","Unsupported operational purpose");var l=locations.findByIdAndTenantIdAndWarehouseId(locationId,a.tenantId(),warehouseId).orElseThrow(()->new WarehouseException("CROSS_WAREHOUSE_LOCATION_REFERENCE","Default location must belong to warehouse"));if(l.status!=StorageLocation.Status.ACTIVE||!l.type.name().equals(purpose))throw new WarehouseException("INVALID_LOCATION_PURPOSE","Location must be active and compatible");jdbc.update("INSERT INTO warehouse_operational_locations VALUES (?,?,?,?) ON CONFLICT(tenant_id,warehouse_id,purpose) DO UPDATE SET location_id=excluded.location_id",a.tenantId(),warehouseId,purpose,locationId);record(a,"WAREHOUSE_DEFAULT_LOCATION_CHANGED","warehouse",warehouseId);}
 @Transactional(readOnly=true)List<StorageLocation> topology(UUID warehouseId){var a=auth.require(Permission.WAREHOUSE_LOCATION_READ);warehouse(warehouseId,a.tenantId());var all=locations.findAllByTenantIdAndWarehouseIdOrderBySequenceAscCodeAsc(a.tenantId(),warehouseId);if(all.size()>20000)throw new WarehouseException("TOPOLOGY_TOO_LARGE","Use paginated locations");return all;}
 @Transactional(readOnly=true)StorageLocation lookup(String scan){var a=auth.require(Permission.WAREHOUSE_LOCATION_READ);return locations.findByTenantIdAndNormalizedScanCode(a.tenantId(),Warehouse.norm(scan)).orElseThrow(()->missing("LOCATION_NOT_FOUND"));}
 public Optional<UsableWarehouse>findActiveWarehouse(UUID tenantId,UUID warehouseId){return warehouses.findByIdAndTenantId(warehouseId,tenantId).filter(w->w.status==Warehouse.Status.ACTIVE).map(w->new UsableWarehouse(w.id,w.code,w.name));}public Optional<UsableLocation>findUsableLocation(UUID tenantId,UUID warehouseId,UUID locationId){Warehouse w=warehouses.findByIdAndTenantId(warehouseId,tenantId).orElse(null);if(w==null||w.status!=Warehouse.Status.ACTIVE)return Optional.empty();return locations.findByIdAndTenantIdAndWarehouseId(locationId,tenantId,warehouseId).filter(l->l.status==StorageLocation.Status.ACTIVE).map(l->new UsableLocation(warehouseId,l.id,l.type.name()));}
 private void validateParent(UUID t,UUID w,UUID z,UUID p,UUID moving){if(p==null)return;StorageLocation parent=locations.findByIdAndTenantIdAndWarehouseId(p,t,w).orElseThrow(()->new WarehouseException("CROSS_WAREHOUSE_LOCATION_REFERENCE","Parent must belong to warehouse"));if(parent.status==StorageLocation.Status.ARCHIVED)throw new WarehouseException("INVALID_LOCATION_PARENT","Archived parent");if(!parent.zoneId.equals(z))throw new WarehouseException("INVALID_LOCATION_PARENT","Parent and child must belong to the same zone");Set<UUID>seen=new HashSet<>();UUID cursor=p;while(cursor!=null){if(!seen.add(cursor)||(moving!=null&&cursor.equals(moving)))throw new WarehouseException("LOCATION_CYCLE","Location hierarchy cycle");cursor=locations.findByIdAndTenantIdAndWarehouseId(cursor,t,w).orElseThrow(()->new WarehouseException("CROSS_WAREHOUSE_LOCATION_REFERENCE","Invalid parent warehouse")).parentId;}}
 private Warehouse warehouse(UUID id,UUID t){return warehouses.findByIdAndTenantId(id,t).orElseThrow(()->missing("WAREHOUSE_NOT_FOUND"));}private StorageLocation location(UUID id,UUID t){return locations.findByIdAndTenantId(id,t).orElseThrow(()->missing("LOCATION_NOT_FOUND"));}private WarehouseZone zone(UUID id,UUID t){return zones.findByIdAndTenantId(id,t).orElseThrow(()->missing("ZONE_NOT_FOUND"));}private void requireZone(UUID id,UUID t,UUID w){zones.findByIdAndTenantIdAndWarehouseId(id,t,w).orElseThrow(()->new WarehouseException("CROSS_WAREHOUSE_ZONE_REFERENCE","Zone must belong to warehouse"));}private void record(AuthorizationService.Access a,String action,String entity,UUID id){audit.record(a,action,entity,id.toString());}
 private static Pageable page(int number,int size,String sort,Set<String> allowed,String fallback){if(number<0||size<1||size>100)throw new WarehouseException("INVALID_PAGINATION","page must be non-negative and size between 1 and 100");String value=sort==null||sort.isBlank()?fallback+",asc":sort;String[] parts=value.split(",",-1);if(parts.length>2||!allowed.contains(parts[0])||(parts.length==2&&!Set.of("asc","desc").contains(parts[1].toLowerCase())))throw new WarehouseException("INVALID_SORT","Unsupported sort");Sort.Direction direction=parts.length==2&&parts[1].equalsIgnoreCase("desc")?Sort.Direction.DESC:Sort.Direction.ASC;return PageRequest.of(number,size,Sort.by(direction,parts[0]).and(Sort.by("id")));}private static int unused(){return 0;}
 private static <E extends Enum<E>>E parse(Class<E> type,String value,String code){if(value==null||value.isBlank())return null;try{return Enum.valueOf(type,value.trim().toUpperCase());}catch(IllegalArgumentException e){throw new WarehouseException(code,"Unsupported filter value");}}private static <E extends Enum<E>>E parseRequired(Class<E> type,String value,String code){E result=parse(type,value,code);if(result==null)throw new WarehouseException(code,"Value is required");return result;}private static WarehouseException missing(String c){return new WarehouseException(c,c.replace('_',' ').toLowerCase());}private static WarehouseException conflict(String c){return new WarehouseException(c,c.replace('_',' ').toLowerCase());}
 record WarehouseRequest(String code,String name,String timezone,String line1,String line2,String postal,String city,String region,String country){}record ZoneRequest(String code,String name,String type,int sequence){}record LocationRequest(UUID zoneId,UUID parentId,String code,String name,String type,int sequence,String scanCode,Long maxWeight,Long maxVolume,Integer maxPallets,Long length,Long width,Long height){}record LocationUpdate(UUID zoneId,String name,String type,int sequence,Long maxWeight,Long maxVolume,Integer maxPallets,Long length,Long width,Long height,long version){}
}
